/*
 * 头部的头像，用于打开用户菜单（Discourse 的 `.header-dropdown-toggle
 * .current-user`）。它继承核心会话菜单按钮的内容
 *（`SessionDropdown.getButtonContent`），因此其他区域放在那里的内容——
 * 资料状态 emoji——仍然会显示；只有名字被移除，与 Discourse 一致。
 *
 * 气泡按 Discourse 的 `user-dropdown/notifications` 顺序：未读消息用
 * 绿色信封（`.new-pms`）；尚未查看的审核项用红旗（`.new-reviewables`）；
 * 否则显示菜单中等待处理的全部数量——未读通知（任意标签页，不只是
 * “新”通知）加上审核队列中的待处理项。
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import SessionDropdown from 'flarum/forum/components/SessionDropdown';
import classList from 'flarum/common/utils/classList';
import { userMenu } from './state';
import { umText } from './text';
import { loadMenu } from './lazy';
import { lazyComponent } from '../utils/lazy';

// 打开的菜单在 chunk 中；指针或焦点落在头像上时就会请求。
const UserMenu = lazyComponent(() => loadMenu().then(chunk => chunk.UserMenu));
const preload = () => void loadMenu().catch(() => {});
export default class UserMenuButton extends Component {
  view() {
    // 导航时菜单关闭（Discourse 的 `routeDidChange`）。头部
    // 每次路由切换都会重绘，因此在这里检查即可。
    if (userMenu.open && userMenu.route !== m.route.get()) userMenu.close();
    const user = app.session.user;
    const unreadDialogs = user.attribute('unreadDialogCount') || 0;
    const canReview = !!app.forum.attribute('canViewFlags') && !!app.flags;
    const newReviewables = canReview ? Number(user.attribute('newFlagCount') || 0) : 0;
    const pendingReviewables = canReview ? Number(app.forum.attribute('flagCount') || 0) : 0;
    const total = (user.unreadNotificationCount() || 0) + pendingReviewables;
    const label = umText('toggle');
    return m("div", {
      className: classList('LcoyUserMenuWrap', {
        'LcoyUserMenuWrap--open': userMenu.open
      })
    }, m("button", {
      type: "button",
      className: classList('Button Button--flat LcoyUserMenuButton', {
        active: userMenu.open
      }),
      "aria-haspopup": "true",
      "aria-expanded": userMenu.open ? 'true' : 'false',
      "aria-controls": "lcoy-user-menu",
      "aria-label": label,
      title: label,
      onmouseenter: preload,
      onfocus: preload,
      ontouchstart: preload,
      onclick: e => {
        e.preventDefault();
        userMenu.toggle();
      }
    }, this.avatarContent(), unreadDialogs > 0 ? m("span", {
      className: "LcoyUserMenuButton-badge LcoyUserMenuButton-badge--pms",
      title: umText('badge.new_messages', {
        count: unreadDialogs
      })
    }, m(Icon, {
      name: "fas fa-envelope"
    })) : newReviewables > 0 ? m("span", {
      className: "LcoyUserMenuButton-badge LcoyUserMenuButton-badge--reviewables",
      title: umText('badge.new_reviewables', {
        count: newReviewables
      })
    }, m(Icon, {
      name: "fas fa-flag"
    })) : total > 0 ? m("span", {
      className: "LcoyUserMenuButton-badge LcoyUserMenuButton-badge--unread",
      title: umText('badge.unread', {
        count: total
      })
    }, total) : null), userMenu.open ? m(UserMenu, null) : null);
  }

  /** 头像（以及附加到它的内容），不含用户名。 */
  avatarContent() {
    const session = Object.create(SessionDropdown.prototype);
    session.attrs = {};
    const children = SessionDropdown.prototype.getButtonContent.call(session);
    return (Array.isArray(children) ? children : [children]).filter(child => {
      if (typeof child === 'string') return false;
      if (child && child.attrs && typeof child.attrs.className === 'string' && child.attrs.className.includes('Button-label')) return false;
      return !!child;
    });
  }
  onupdate(vnode) {
    super.onupdate(vnode);

    // 通过 Esc 关闭：焦点回到头像。
    if (!userMenu.open && userMenu.restoreFocus) {
      userMenu.restoreFocus = false;
      this.element.querySelector('.LcoyUserMenuButton')?.focus();
    }
  }
}
flarum.reg.add('lcoy-roselle', 'forum/usermenu/UserMenuButton', UserMenuButton);