/*
 * 在不依赖构建时 flarum/tags 的情况下访问标签。
 *
 * 主题在没有标签扩展时也能工作：没有它，模型中没有
 * `discussion.tags`，`app.currentTag` 也未定义。主题需要的少量信息
 * （名称、颜色、图标、层级）直接从模型读取，两种情况下
 * 模型都相同。
 */
import app from 'flarum/forum/app';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import { forumBool, isExtensionEnabled } from './settings';
export function isTagsEnabled() {
  return isExtensionEnabled('flarum-tags');
}
export function allTags() {
  return isTagsEnabled() ? app.store.all('tags') : [];
}

/**
 * 与 flarum/tags 相同的顺序：主标签按位置，子标签紧跟在
 * 父标签之后，二级标签按名称。
 */
export function sortTags(tags) {
  return tags.slice().sort((a, b) => {
    const aParent = a.isChild() ? a.parent() : null;
    const bParent = b.isChild() ? b.parent() : null;
    const aPos = a.position();
    const bPos = b.position();
    if (aParent && aParent === bParent) return (aPos ?? 0) - (bPos ?? 0);
    if (aParent && bParent) return (aParent.position() ?? 0) - (bParent.position() ?? 0);
    if (aParent) return aParent === b ? 1 : (aParent.position() ?? 0) - (bPos ?? 0);
    if (bParent) return bParent === a ? -1 : (aPos ?? 0) - (bParent.position() ?? 0);
    if (aPos === null && bPos === null) return b.discussionCount() - a.discussionCount();
    if (bPos === null) return -1;
    if (aPos === null) return 1;
    return aPos - bPos;
  });
}

/** Discourse 的“分类”：一级主标签。 */
export function primaryTags() {
  return sortTags(allTags().filter(tag => tag.position() !== null && !tag.isChild()));
}

/** Discourse 的“标签”：二级标签，最常用的在前。 */
export function secondaryTags() {
  return allTags().filter(tag => tag.position() === null).sort((a, b) => b.discussionCount() - a.discussionCount());
}
export function discussionTags(discussion) {
  if (!isTagsEnabled()) return [];
  const tags = discussion.tags?.();
  return Array.isArray(tags) ? sortTags(tags.filter(Boolean)) : [];
}

/** 像 Discourse 区分分类和标签那样拆分讨论的标签。 */
export function splitDiscussionTags(discussion) {
  const tags = discussionTags(discussion);
  return {
    categories: tags.filter(tag => tag.position() !== null),
    labels: tags.filter(tag => tag.position() === null)
  };
}
export function currentTag() {
  if (!isTagsEnabled()) return null;
  return app.currentTag?.() ?? null;
}

/**
 * 启用 Discourse 的地址后，/categories 是分类页，
 * /tags 是标签页；没有它们时，/tags（来自 flarum/tags）兼任两者。
 */
export function separateTagsPage() {
  return forumBool('lcoyListRoutes', false);
}

/** 分类页的路由。 */
export function categoriesRouteName() {
  return separateTagsPage() ? 'lcoy.categories' : 'tags';
}
export function categoriesUrl() {
  return app.route(categoriesRouteName());
}
export function tagUrl(tag) {
  return app.route('tag', {
    tags: tag.slug()
  });
}

/**
 * 像 Discourse 绘制的那样显示分类符号：使用其颜色的图标，或
 * 没有图标时，一个实心小方块。
 */
export function categorySymbol(tag, className = '') {
  const color = tag?.color() || '';
  const icon = tag?.icon();
  return m("span", {
    className: classList('LcoyCategorySymbol', className, {
      'LcoyCategorySymbol--square': !icon
    }),
    style: color ? {
      '--category-color': color
    } : undefined,
    "aria-hidden": "true"
  }, icon ? m(Icon, {
    name: icon
  }) : null);
}

/**
 * 没有图标的子标签的符号：双色小方块，父标签的颜色和
 * 它自己的颜色（`.badge-category.--has-parent::before`）。
 */
function childSymbol(tag, parent) {
  const symbol = categorySymbol(tag);
  if (!tag.icon() && symbol?.attrs) {
    symbol.attrs.className = classList(symbol.attrs.className, 'LcoyCategorySymbol--split');
    symbol.attrs.style = {
      ...(symbol.attrs.style || {}),
      '--category-parent-color': parent.color() || 'var(--lcoy-primary-medium)'
    };
  }
  return symbol;
}

/**
 * “▪ 支持”——Discourse 的分类徽标，可带链接。有父标签时，
 * 变成子分类徽标：“▪ 支持 ▪ 安装”，只有一个链接
 * （指向子标签）。
 */
export function categoryBadge(tag, link = true, parent = null) {
  const content = parent ? [categorySymbol(parent), m("span", {
    className: "LcoyCategoryBadge-name LcoyCategoryBadge-parent"
  }, parent.name()), childSymbol(tag, parent), m("span", {
    className: "LcoyCategoryBadge-name"
  }, tag.name())] : [categorySymbol(tag), m("span", {
    className: "LcoyCategoryBadge-name"
  }, tag.name())];
  const attrs = {
    className: 'LcoyCategoryBadge',
    title: tag.description() || undefined
  };
  return link ? m(Link, Object.assign({}, attrs, {
    href: tagUrl(tag)
  }), content) : m("span", attrs, content);
}

/**
 * 按 Flarum 的定义显示标签图标（有颜色时使用其颜色）。
 * 没有图标时，使用 `fallback`（例如侧栏的通用标签）或什么都不显示。
 * 图标放在带 `--tag-color` 的 <span> 中，因为颜色由各处
 * CSS（列表、侧栏、搜索）应用，缺少颜色时由它们决定色调。
 */
export function tagSymbol(tag, className = '', fallback = null) {
  const icon = tag?.icon() || fallback;
  if (!icon) return null;
  const color = tag?.color() || '';
  return m("span", {
    className: classList('LcoyTagSymbol', className, {
      'LcoyTagSymbol--colored': !!color
    }),
    style: color ? {
      '--tag-color': color
    } : undefined,
    "aria-hidden": "true"
  }, m(Icon, {
    name: icon
  }));
}

/** 采用 Discourse “simple” 样式的标签（二级标签）：有则显示 Flarum 的图标，以及文本。 */
export function labelBadge(tag, link = true) {
  const attrs = {
    className: 'LcoyTagBadge',
    title: tag.description() || undefined
  };
  const content = [tagSymbol(tag), m("span", null, tag.name())];
  return link ? m(Link, Object.assign({}, attrs, {
    href: tagUrl(tag)
  }), content) : m("span", attrs, content);
}

/** 分类后跟标签，位于标题下方一行。 */
export function discussionBadges(discussion, link = true) {
  const {
    categories,
    labels
  } = splitDiscussionTags(discussion);
  if (!categories.length && !labels.length) return null;

  // 父标签也在讨论中的子标签会变成一个“父 ▪ 子”徽标；
  // 父标签不会再单独显示。
  const childOf = tag => {
    const parent = tag.isChild() ? tag.parent() : null;
    return parent && categories.includes(parent) ? parent : null;
  };
  const parentsShown = new Set(categories.map(childOf).filter(Boolean));
  return m("span", {
    className: "LcoyBadges"
  }, categories.filter(tag => !parentsShown.has(tag)).map(tag => categoryBadge(tag, link, childOf(tag))), labels.length > 0 && m("span", {
    className: "LcoyBadges-labels"
  }, labels.map(tag => labelBadge(tag, link))));
}
flarum.reg.add('lcoy-roselle', 'forum/utils/tags', { isTagsEnabled: isTagsEnabled,allTags: allTags,sortTags: sortTags,primaryTags: primaryTags,secondaryTags: secondaryTags,discussionTags: discussionTags,splitDiscussionTags: splitDiscussionTags,currentTag: currentTag,separateTagsPage: separateTagsPage,categoriesRouteName: categoriesRouteName,categoriesUrl: categoriesUrl,tagUrl: tagUrl,categorySymbol: categorySymbol,categoryBadge: categoryBadge,tagSymbol: tagSymbol,labelBadge: labelBadge,discussionBadges: discussionBadges, });