/*
 * 读取 extend.php 在论坛中序列化的主题配置
 * （`lcoy*`）。PHP 已经转换了布尔值和整数，但属性在启用扩展后
 * 的一瞬间可能缺失——因此需要默认值。
 */
import app from 'flarum/forum/app';
export function forumBool(attributeName, fallback = false) {
  // 在 initializer 中 `app.forum` 还不存在：使用默认值。
  if (!app.forum) return fallback;
  const value = app.forum.attribute(attributeName);
  return value === undefined || value === null ? fallback : !!value;
}
export function forumInt(attributeName, fallback) {
  if (!app.forum) return fallback;
  const value = Number(app.forum.attribute(attributeName));
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : fallback;
}

/** 将主题翻译直接作为字符串获取的快捷方式（标题、aria-label……）。 */
export function t(key, params = {}) {
  return app.translator.trans(`lcoy-roselle.forum.${key}`, params, true);
}
export function isExtensionEnabled(id) {
  return id in flarum.extensions;
}
flarum.reg.add('lcoy-roselle', 'forum/utils/settings', { forumBool: forumBool,forumInt: forumInt,t: t,isExtensionEnabled: isExtensionEnabled, });