/*
 * /reset/{token}：“重置密码”页面，外观与登录页面一致（logo、
 * 卡片、标题、带浮动标签的字段），替代核心的简陋页面。
 * 服务端（src/Auth/ResetPasswordContent）按核心的方式校验 token，
 * 并下发 token 及上次尝试的错误；表单提交到核心的 POST /reset
 * （SavePasswordController），由它更换密码、登录并跳回首页——
 * 若出错则带着错误信息返回本页。
 */
import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import { t } from '../../utils/settings';
import { authLogo, backToLogin } from './AuthPage';
export default class ResetPasswordPage extends Page {
  bodyClass = 'Lcoy--authPage';
  loading = false;
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(t('auth.reset_heading'));
    app.setTitleCount(0);
  }
  payload() {
    const data = app.data.lcoyReset;

    // 只认可当前 URL 中的 token（payload 属于首次加载）。
    return data && data.token === m.route.param('token') ? data : null;
  }
  view() {
    const data = this.payload();
    return m("div", {
      className: "LcoyAuthPage LcoyAuthPage--reset"
    }, m("div", {
      className: "LcoyAuthPage-inner"
    }, authLogo(), m("div", {
      className: "Modal modal-dialog LcoyAuthForm LcoyResetForm"
    }, m("div", {
      className: "Modal-content"
    }, data ? this.form(data) : this.unavailable())), backToLogin()));
  }
  form(data) {
    return m("form", {
      method: "POST",
      action: `${app.forum.attribute('baseUrl')}/reset`,
      onsubmit: () => this.loading = true
    }, m("div", {
      className: "Modal-header"
    }, m("h3", {
      className: "App-titleControl App-titleControl--text"
    }, t('auth.reset_heading'))), data.errors.length ? m("div", {
      className: "Modal-alert"
    }, m("div", {
      className: "Alert Alert--error",
      role: "alert"
    }, m("span", {
      className: "Alert-body"
    }, data.errors.map(error => m("p", null, error))))) : null, m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form Form--centered"
    }, m("input", {
      type: "hidden",
      name: "csrfToken",
      value: app.session.csrfToken
    }), m("input", {
      type: "hidden",
      name: "passwordToken",
      value: data.token
    }), m("p", {
      className: "helpText"
    }, t('auth.reset_help')), this.field('password', t('auth.reset_new_password'), true), this.field('password_confirmation', t('auth.reset_confirm_password'), false), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit",
      loading: this.loading
    }, t('auth.reset_submit'))))));
  }
  field(name, label, focus) {
    return m("div", {
      className: "Form-group LcoyFloat"
    }, m("input", {
      className: "FormControl",
      type: "password",
      name: name,
      autocomplete: "new-password",
      placeholder: " ",
      "aria-label": label,
      required: true,
      minlength: 8,
      oncreate: focus ? vnode => vnode.dom.focus() : undefined
    }), m("label", {
      className: "LcoyFloat-label",
      "aria-hidden": "true"
    }, label));
  }

  /** 在论坛内部导航到达此处（无服务端 payload）：刷新页面。 */
  unavailable() {
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, m("a", {
      href: window.location.href,
      onclick: () => window.location.reload()
    }, t('auth.reset_heading'))));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/auth/ResetPasswordPage', ResetPasswordPage);