/*
 * fof/reactions，按照 discourse-reactions 的方式呈现。
 *
 * 在主题的操作栏和 flarum/likes 启用时，点赞与回应
 * 合并为一个按钮，与 Discourse 相同：
 *
 * - 栏中的心形：点击点赞（或取消）；悬停（或在移动端长按）
 *   会在上方打开选择器，显示 fof/reactions 已启用的回应，
 *   按其顺序排列。fof 的 "heart" 回应，无论位于列表何处，
 *   都是 flarum/likes 的点赞；其他则是 fof 的回应。每个人
 *   对每个帖子只能有一个回应：在已点赞时选择某个 emoji
 *   会取消点赞，在已有 emoji 时选择心形会移除该回应。
 *   回应后，按钮显示所选的 emoji；点击它会取消。
 * - 左侧只有一个计数：最多三个 emoji（最常用的在前，
 *   包含点赞的心形）叠加显示，再加上总数。点击会打开
 *   回应者列表，每人显示自己的 emoji。
 *
 * 没有主题的操作栏或没有 flarum/likes 时，fof 的回应按钮
 * 仍然保留（使用相同的网格选择器），摘要显示在点赞旁边。
 */
import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import CommentPost from 'flarum/forum/components/CommentPost';
import PostControls from 'flarum/forum/utils/PostControls';
import abbreviateNumber from 'flarum/common/utils/abbreviateNumber';
import classList from 'flarum/common/utils/classList';
import haptic from 'flarum/common/utils/haptic';
import { isExtensionEnabled, t } from '../utils/settings';
import { extModule, thirdParty } from './settings';
import { postUi, topicSettings } from '../topic/ui';
import { likers } from '../topic/posts';
import { heartIcon, openWhoReacted } from '../topic/components/WhoReactedPopover';

/** 摘要显示多少个 emoji（Discourse 中 `nth-of-type(1n + 4)` 会隐藏）。 */
const SUMMARY_EMOJIS = 3;

/** fof 中代表 flarum/likes 点赞的回应。 */
const HEART = 'heart';

/** discourse-reactions 的延迟：悬停打开、离开关闭、长按。 */
const OPEN_DELAY = 250;
const CLOSE_DELAY = 300;
const LONG_PRESS = 400;

/** 选择器与窗口边缘的最小距离。 */
const EDGE = 8;
function reactionComponent() {
  return extModule('fof-reactions', 'common/components/ReactionComponent');
}
function reactToPostFn() {
  const mod = extModule('fof-reactions', 'forum/utils/reactToPost');
  return mod ? mod.default || mod : null;
}

/**
 * fof/reactions 已启用的回应，按其顺序（由 fof 的
 * 管理员管理）：帖子选择器和私信选择器都使用这个列表。
 */
export function enabledReactions() {
  const fromForum = app.forum?.reactions?.();
  const list = Array.isArray(fromForum) && fromForum.length ? fromForum : app.store.all('reactions');
  return list.filter(reaction => reaction && reaction.enabled?.() !== false);
}
function heartReaction() {
  return app.store.all('reactions').find(reaction => reaction.identifier?.() === HEART) || null;
}

/** 点赞的 ❤️：使用 fof 的 emoji，以便与其他保持一致；没有它时用图标。 */
function heartEmoji() {
  const ReactionComponent = reactionComponent();
  const heart = heartReaction();
  return ReactionComponent && heart ? m(ReactionComponent, {
    reaction: heart
  }) : heartIcon();
}
function reactionEmoji(reaction) {
  const ReactionComponent = reactionComponent();
  return ReactionComponent && reaction ? m(ReactionComponent, {
    reaction
  }) : null;
}
function reactionLabel(reaction) {
  return String(reaction?.display?.() || reaction?.identifier?.() || '');
}
function counts(post) {
  const raw = post.reactionCounts?.() || {};
  return Object.keys(raw).map(id => [id, Number(raw[id]) || 0]).filter(([id, count]) => count > 0 && !!app.store.getById('reactions', id)).sort((a, b) => b[1] - a[1]);
}

/** 在主题的操作栏和两个扩展都具备时才进行合并。 */
function unified() {
  return thirdParty.reactions() && topicSettings.postActions() && isExtensionEnabled('flarum-likes');
}
function isLiked(post) {
  const user = app.session.user;
  return !!user && (post.likes?.() || []).some(liker => liker === user);
}

/** 读者在该帖子上的 fof 回应（"heart" 计为点赞）。 */
function myReaction(post) {
  const id = post.userReaction?.();
  const counted = id && Number((post.reactionCounts?.() || {})[id]) > 0;
  return counted ? app.store.getById('reactions', String(id)) || null : null;
}

/**
 * 按 flarum/likes 的方式点赞/取消点赞，但返回 promise（以便
 * 随后把点赞换成 emoji），并立即更新计数。
 */
function setLiked(post, value) {
  const user = app.session.user;
  const data = post.data;
  const relationships = data.relationships ??= {};
  const likes = (relationships.likes ??= {
    data: []
  }).data;
  const index = likes.findIndex(like => like.id === user.id());
  const count = Number(post.attribute('likesCount')) || 0;
  if (index !== -1) likes.splice(index, 1);
  if (value) likes.unshift({
    type: 'users',
    id: user.id()
  });
  if (value) haptic('success');

  // 改变帖子的 "新鲜度"：SubtreeRetainer 会立即重绘。
  post.pushAttributes({
    likesCount: Math.max(0, count + (value ? 1 : -1))
  });
  m.redraw();
  return post.save({
    isLiked: value
  }).catch(() => {});
}

// ---------------------------------------------------------------------------
// 回应者
// ---------------------------------------------------------------------------

/** fof PostReaction 的关系（或属性）id。 */
function relatedId(item, relation, attribute) {
  const id = item?.data?.relationships?.[relation]?.data?.id ?? item?.attribute?.(attribute);
  return id === null || id === undefined ? null : String(id);
}

/**
 * 使用 emoji 回应的人。fof 2.x 的 PostReaction 模型不会解析
 * 关系（`user()` 返回 getter，`reaction()` 读取一个不
 * 存在的属性）：用户和回应通过响应中已包含的 id 获取。
 */
function reactors(post) {
  return app.store.find('post_reactions', {
    filter: {
      post: post.id()
    },
    include: 'user,reaction',
    page: {
      limit: 50
    }
  }, undefined, {
    errorHandler: () => {}
  }).then(list => Array.from(list || []).map(item => {
    const userId = relatedId(item, 'user', 'userId');
    const reactionId = relatedId(item, 'reaction', 'reactionId');
    return {
      user: userId ? app.store.getById('users', userId) : null,
      reaction: reactionId ? app.store.getById('reactions', reactionId) : null
    };
  }).filter(entry => entry.user && entry.reaction).map(entry => ({
    user: entry.user,
    icon: reactionEmoji(entry.reaction)
  })));
}

/** 点赞者（带 ❤️）和使用 emoji 回应的人，合并在一个弹出层中。 */
function everyone(post, canSeeReactions) {
  const likes = likers(post).then(entries => entries.map(entry => ({
    ...entry,
    icon: heartEmoji()
  }))).catch(() => []);
  const others = canSeeReactions ? reactors(post).catch(() => []) : Promise.resolve([]);
  return Promise.all([likes, others]).then(([a, b]) => a.concat(b));
}

// ---------------------------------------------------------------------------
// 左侧的摘要
// ---------------------------------------------------------------------------

function summaryButton(entries, onclick) {
  const total = entries.reduce((sum, entry) => sum + entry.count, 0);
  const label = t('thirdparty.reactions.summary', {
    count: total
  });
  const body = [m("span", {
    className: "LcoyReactions-list"
  }, entries.slice(0, SUMMARY_EMOJIS).map(entry => m("span", {
    className: "LcoyReactions-emoji"
  }, entry.icon))), m("span", {
    className: "LcoyReactions-count"
  }, abbreviateNumber(total))];
  return onclick ? m(Button, {
    className: "Button Button--flat LcoyPostAction LcoyReactions",
    "aria-haspopup": "dialog",
    "aria-label": label,
    title: label,
    onclick: onclick
  }, body) : m("span", {
    className: "LcoyReactions LcoyReactions--static",
    "aria-label": label,
    title: label
  }, body);
}
function unifiedSummary(post) {
  const heart = heartReaction();
  const heartId = heart ? String(heart.id()) : null;
  const likeCount = Number(post.attribute('likesCount')) || (post.likes?.() || []).length;
  let hearts = likeCount;
  const entries = [];
  counts(post).forEach(([id, count]) => {
    if (id === heartId) hearts += count;else entries.push({
      key: id,
      count,
      icon: reactionEmoji(app.store.getById('reactions', id))
    });
  });
  if (hearts > 0) entries.push({
    key: HEART,
    count: hearts,
    icon: heartEmoji()
  });
  if (!entries.length) return null;

  // 最常用的在前；相同时，心形优先。
  entries.sort((a, b) => b.count - a.count || (a.key === HEART ? -1 : b.key === HEART ? 1 : 0));
  const canSee = !!post.discussion()?.canSeeReactions?.();

  // 没有查看回应者的权限且没有点赞（点赞是公开的）时，
  // 列表会是空的：摘要只作为计数，不打开任何内容。
  if (!canSee && likeCount === 0) return summaryButton(entries, null);
  return summaryButton(entries, event => openWhoReacted(event.currentTarget, () => everyone(post, canSee)));
}

// ---------------------------------------------------------------------------
// 带选择器的心形按钮
// ---------------------------------------------------------------------------

function choices(post) {
  if (!app.session.user) return [];
  const canLike = !!post.canLike?.();
  const canReact = !!post.canReact?.();
  const mine = myReaction(post);
  const liked = isLiked(post);
  const list = [];
  let heartAdded = false;
  const addHeart = () => {
    if (heartAdded || !canLike) return;
    heartAdded = true;
    list.push({
      key: HEART,
      label: t('thirdparty.reactions.like_reaction'),
      icon: heartEmoji(),
      used: liked && (!mine || mine.identifier?.() === HEART),
      reaction: null
    });
  };
  enabledReactions().forEach(reaction => {
    if (reaction.identifier?.() === HEART) return addHeart();
    if (!canReact) return;
    list.push({
      key: String(reaction.id()),
      label: reactionLabel(reaction),
      icon: reactionEmoji(reaction),
      used: !!mine && mine === reaction,
      reaction
    });
  });

  // 没有在 fof 中启用 "heart" 时，点赞排在最前，与 Discourse 相同。
  if (!heartAdded && canLike) {
    addHeart();
    list.unshift(list.pop());
  }
  return list;
}
class LcoyReactButton {
  open = false;
  element = null;
  hoverTimer = 0;
  pressTimer = 0;
  suppressClick = false;
  loading = {};
  onDocument = event => {
    if (!this.open || !this.element) return;
    if (event instanceof KeyboardEvent) {
      if (event.key === 'Escape') {
        this.setOpen(false);
        this.element.querySelector('.LcoyReact-button')?.focus();
      }
      return;
    }
    if (!this.element.contains(event.target)) this.setOpen(false);
  };
  view(vnode) {
    this.attrs = vnode.attrs;
    const {
      post,
      ui
    } = vnode.attrs;
    const guest = !app.session.user;
    const mine = myReaction(post);
    const emojiMine = mine && mine.identifier?.() !== HEART ? mine : null;
    const liked = isLiked(post) || !!mine && !emojiMine;
    // 只有心形（例如在自己的帖子上没有回应权限）：按钮
    // 本身就会点赞，因此没有选择器 —— 与 Discourse 相同。
    const all = choices(post);
    const list = all.length === 1 && all[0].key === HEART ? [] : all;
    const label = guest ? t('topic.post.like_guest') : emojiMine ? t('thirdparty.reactions.remove') : t(liked ? 'topic.post.unlike' : 'topic.post.like');
    return m("div", {
      className: classList('LcoyReact', {
        'is-open': this.open,
        'has-reacted': liked || !!emojiMine,
        'has-picker': list.length > 0
      }),
      onpointerenter: event => this.hover(event, true),
      onpointerleave: event => this.hover(event, false),
      onfocusout: event => {
        if (this.element && !this.element.contains(event.relatedTarget)) this.setOpen(false);
      }
    }, m(Button, {
      className: classList('Button Button--flat LcoyPostAction LcoyReact-button', {
        'Button--icon LcoyLike-toggle': !emojiMine,
        'LcoyLike--liked': !emojiMine && liked,
        'LcoyLike--bump': !emojiMine && liked && ui.likeBump && Date.now() - ui.likeBump < 1000,
        'LcoyReact-button--emoji': !!emojiMine
      }),
      icon: emojiMine ? undefined : liked ? 'fas fa-heart' : 'far fa-heart',
      "aria-label": label,
      "aria-pressed": liked || emojiMine ? 'true' : 'false',
      "aria-haspopup": list.length ? 'menu' : undefined,
      "aria-expanded": list.length ? this.open ? 'true' : 'false' : undefined,
      title: label,
      loading: !!this.loading[null],
      onpointerdown: event => this.press(event),
      onpointerup: () => window.clearTimeout(this.pressTimer),
      onpointercancel: () => window.clearTimeout(this.pressTimer),
      oncontextmenu: event => {
        if (this.open) event.preventDefault();
      },
      onkeydown: event => {
        if (event.key !== 'ArrowUp' || !list.length) return;
        event.preventDefault();
        this.setOpen(true);
        this.element?.querySelector('.LcoyReactPicker-item')?.focus();
      },
      onclick: () => this.main()
    }, emojiMine ? reactionEmoji(emojiMine) : null), list.length ? m("div", {
      className: "LcoyReactPicker",
      role: "menu",
      "aria-label": t('thirdparty.reactions.picker')
    }, m("div", {
      className: "LcoyReactPicker-container",
      style: `--lcoy-react-cols: ${Math.min(7, list.length)}`
    }, list.map(choice => m("button", {
      type: "button",
      role: "menuitem",
      className: classList('LcoyReactPicker-item', {
        'is-used': choice.used
      }),
      title: choice.label,
      "aria-label": t('thirdparty.reactions.react_with', {
        reaction: choice.label
      }),
      onclick: event => {
        event.stopPropagation();
        this.pick(choice);
      }
    }, choice.icon)))) : null);
  }
  oncreate(vnode) {
    this.element = vnode.dom;
  }
  onupdate(vnode) {
    this.element = vnode.dom;
  }
  onremove() {
    window.clearTimeout(this.hoverTimer);
    window.clearTimeout(this.pressTimer);
    this.unlisten();
  }
  hasPicker() {
    return !!this.element?.querySelector('.LcoyReactPicker');
  }

  /** 选择器以 Discourse 的延迟打开（或关闭），仅限鼠标。 */
  hover(event, inside) {
    if (event.pointerType !== 'mouse' || !this.hasPicker()) return;
    window.clearTimeout(this.hoverTimer);
    this.hoverTimer = window.setTimeout(() => this.setOpen(inside), inside ? OPEN_DELAY : CLOSE_DELAY);
  }

  /** 触摸时，按住心形会打开选择器（随后的点击不会点赞）。 */
  press(event) {
    this.suppressClick = false;
    if (event.pointerType === 'mouse' || !this.hasPicker()) return;
    window.clearTimeout(this.pressTimer);
    this.pressTimer = window.setTimeout(() => {
      this.suppressClick = true;
      haptic('selection');
      this.setOpen(true);
    }, LONG_PRESS);
  }

  /**
   * 直接操作类名来打开/关闭：帖子由
   * SubtreeRetainer 保留，不会因为这一部分的局部状态而重绘。
   */
  setOpen(open) {
    window.clearTimeout(this.hoverTimer);
    if (this.open === open) return;
    this.open = open;
    const el = this.element;
    if (!el) return;
    el.classList.toggle('is-open', open);
    el.querySelector('.LcoyReact-button')?.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) {
      this.place();
      document.addEventListener('pointerdown', this.onDocument, true);
      document.addEventListener('keydown', this.onDocument, true);
    } else {
      this.unlisten();
    }
  }
  unlisten() {
    document.removeEventListener('pointerdown', this.onDocument, true);
    document.removeEventListener('keydown', this.onDocument, true);
  }

  /** 与按钮左对齐（与 Meta 相同），且不超出窗口。 */
  place() {
    const picker = this.element?.querySelector('.LcoyReactPicker');
    if (!picker) return;
    picker.style.setProperty('--lcoy-react-shift', '0px');
    const rect = picker.getBoundingClientRect();
    const overflowRight = rect.right - (document.documentElement.clientWidth - EDGE);
    let shift = 0;
    if (overflowRight > 0) shift = -overflowRight;
    if (rect.left + shift < EDGE) shift = EDGE - rect.left;
    picker.style.setProperty('--lcoy-react-shift', `${Math.round(shift)}px`);
  }
  main() {
    if (this.suppressClick) {
      this.suppressClick = false;
      return;
    }
    const {
      post,
      ui
    } = this.attrs;
    if (!app.session.user) {
      app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
      return;
    }
    this.setOpen(false);
    const mine = myReaction(post);
    if (mine) {
      this.react(null);
      return;
    }
    if (post.canLike?.()) {
      const liked = isLiked(post);
      if (!liked) ui.likeBump = Date.now();
      setLiked(post, !liked);
      return;
    }

    // 无法点赞（例如自己的帖子）时，点击会打开选择器。
    if (this.hasPicker()) this.setOpen(true);
  }
  react(reaction) {
    const fn = reactToPostFn();
    if (!fn) return Promise.resolve();
    return Promise.resolve(fn(this.attrs.post, reaction, this.loading)).then(() => m.redraw());
  }
  async pick(choice) {
    const {
      post,
      ui
    } = this.attrs;
    const mine = myReaction(post);
    const liked = isLiked(post);
    this.setOpen(false);
    if (choice.key === HEART) {
      if (choice.used) {
        if (mine) await this.react(null);
        if (liked) await setLiked(post, false);
        return;
      }
      if (mine) await this.react(null);
      ui.likeBump = Date.now();
      await setLiked(post, true);
      return;
    }
    if (choice.used) {
      await this.react(null);
      return;
    }
    if (liked) await setLiked(post, false);
    await this.react(choice.reaction);
  }
}

// ---------------------------------------------------------------------------

function unifiedActions(component, post, items) {
  items.remove('react');
  items.remove('lcoyLikeCount');
  const summary = unifiedSummary(post);
  if (summary) items.add('lcoyReactions', summary, 1050);
  const guest = !app.session.user;
  if (!guest && !post.canLike?.() && !post.canReact?.()) {
    items.remove('like');
    return;
  }
  const button = m(LcoyReactButton, {
    post,
    ui: postUi(component)
  });
  if (items.has('like')) items.setContent('like', button);else items.add('like', button, 20);
}
function legacySummary(post, items) {
  const list = counts(post);
  if (!list.length) return;
  const canSee = !!post.discussion()?.canSeeReactions?.();
  const entries = list.map(([id, count]) => ({
    key: id,
    count,
    icon: reactionEmoji(app.store.getById('reactions', id))
  }));
  items.add('lcoyReactions', summaryButton(entries, canSee ? event => openWhoReacted(event.currentTarget, () => reactors(post)) : null), 1050);
}
export default function installReactions() {
  extend(CommentPost.prototype, 'footerItems', function (items) {
    if (!thirdParty.reactions()) return;
    items.remove('reactionCounts');
  });

  // 在 beforeMount 中，与主题的操作栏（topic/index.ts）相同：在它之后
  // 注册，就在它之后运行，并能看到它已重新处理的点赞按钮。
  app.beforeMount(() => {
    extend(CommentPost.prototype, 'actionItems', function (items) {
      if (!thirdParty.reactions()) return;
      const post = this.attrs.post;
      if (post.isHidden()) return;
      if (unified()) unifiedActions(this, post, items);else legacySummary(post, items);
    });
  });

  // fof 放在帖子控件中的 "查看回应"（心形）会与操作栏左侧的
  // 摘要重复，而摘要本身就能打开回应者：在 Discourse 中
  // 心形只出现一次。
  app.beforeMount(() => {
    extend(PostControls, 'moderationControls', function (items) {
      if (thirdParty.reactions() && topicSettings.postActions() && items.has('viewReactions')) items.remove('viewReactions');
    });
  });

  // 合并时 fof 的按钮消失，即使它在主题之后加入。
  override('ext:fof/reactions/forum/components/PostReactAction', 'view', function (original) {
    return unified() ? null : original();
  });

  // 不合并时：使用 fof 的选择器，显示已启用的回应，按其顺序。
  override('ext:fof/reactions/forum/components/PostReactAction', 'unreactButton', function (original) {
    if (!thirdParty.reactions()) return original();
    const post = this.post;
    const mine = app.store.getById('reactions', post.userReaction?.());
    const reactToPost = reactToPostFn();
    if (!mine || !reactionComponent() || !reactToPost) return original();
    const label = app.translator.trans('fof-reactions.forum.unreact_button_label', {}, true);
    return m(Button, {
      className: "Button Button--link Reactions--ShowReactions LcoyReactions-mine",
      title: label,
      "aria-label": label,
      loading: this.loading?.[null],
      onclick: () => reactToPost(post, null, this.loading)
    }, reactionEmoji(mine));
  });
}
flarum.reg.add('lcoy-roselle', 'forum/thirdparty/reactions', installReactions);