/*
 * Horizon 的欢迎横幅：大标题、管理员的欢迎
 * 消息，以及位于页面淡色背景上的胶囊形搜索框。
 *
 * 继承核心的 Hero 以保留 `.Hero` 类 —— IndexPage 会测量它的
 * 高度，以便把读者带回列表中的同一位置。
 */
import app from 'flarum/forum/app';
import Hero from 'flarum/forum/components/Hero';
import GlobalSearch from 'flarum/forum/components/GlobalSearch';
import ItemList from 'flarum/common/utils/ItemList';
import { forumBool } from '../utils/settings';
export default class WelcomeBanner extends Hero {
  className() {
    return 'LcoyWelcome';
  }
  bodyItems() {
    const items = new ItemList();
    const title = app.forum.attribute('welcomeTitle')?.trim() || app.forum.attribute('title');
    const message = app.forum.attribute('welcomeMessage')?.trim();
    items.add('text', m("div", {
      className: "LcoyWelcome-text"
    }, m("h1", {
      className: "LcoyWelcome-title"
    }, title), message ? m("div", {
      className: "LcoyWelcome-message"
    }, m.trust(message)) : null), 100);
    if (forumBool('lcoyWelcomeBannerSearch', true)) {
      items.add('search', m("div", {
        className: "LcoyWelcome-search"
      }, m(GlobalSearch, {
        state: app.search.state
      })), 50);
    }
    return items;
  }
}
flarum.reg.add('lcoy-roselle', 'forum/list/WelcomeBanner', WelcomeBanner);